@spec tv_wide_cc_entry_spec  src=tests/specs/tv_wide_cc_entry_spec.lua  loc=86  cases=5
@exercises trackerView (h.vm), editCursor (h.ec), midiManager (h.fm), trackerManager (h.tm)
@surface   vm:setGridSize, ec:setPos, vm:editEvent, fm:dump, tm:bindTake, fm:seed, vm:rebuild
@harness   mk{seed.ccs}, reaper:bindTake

# Intent
  14-bit cc grid entry. A `14bit` column flag (the columnDisplay track-DS key,
  stamped onto the gridCol at rebuild) widens the scalar to 4 hex digits over a
  display integer (val*256, even last: 0000..7FFE). editEvent stores the
  fractional cc mm's blob splits to an MSB/LSB pair. see design/fx-patterns.md

# Helpers
  @fn ccCol(h)  @ 8-12
  @fn mk(harness)  @ 14-21
  @fn typeHex(h, stop, ch)  @ 25-29
      -- One hex nibble at `stop` (1..4 = MS..LS), row 0 re-pinned each call since
      -- editEvent's commit auto-steps the cursor row.
  @fn ccVal(h)  @ 31-34

# Cases
  @case 'flagged cc column widens to 4 hex stops'  [harness]  @ 38-43
  @case 'the flag is the track\'s: a second take on it opens 14-bit too'  [harness]  @ 47-57
  @case 'MS nibble sets the high byte: 7 at stop 1 -> val 112'  [harness]  @ 61-66
  @case 'value clamps to 0x7FFE: F at stop 1 -> 127+127/128'  [harness]  @ 70-75
  @case 'last nibble forced even: 3 at stop 4 -> 2/256'  [harness]  @ 79-84

# Uses (outbound edges)
  @use call vm:setGridSize  @ 19
  @use call ec:setPos  @ 27
  @use call vm:editEvent  @ 28
  @use call fm:dump  @ 32
  @use call tm:bindTake  @ 51
  @use call fm:seed  @ 52
  @use call vm:rebuild  @ 53

# Fields (r read / w write incl. constructor keys)
  @field r cc  @ 10
  @field w cc  @ 16,52
  @field r ccs  @ 32
  @field w ccs  @ 16,17,52
  @field r cells  @ 28
  @field w chan  @ 16,52
  @field r cols  @ 9
  @field w columnDisplay  @ 17
  @field w data  @ 17
  @field w evType  @ 16,52
  @field r grid  @ 9
  @field w name  @ 38,47,61,70,79
  @field w ppq  @ 16,52
  @field w run  @ 39,48,62,71,80
  @field w seed  @ 16
  @field w shape  @ 16,52
  @field r stopPos  @ 42
  @field r type  @ 10
  @field r val  @ 33
  @field w val  @ 16,52
